def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    found=[]
    for color in set(v for row in grid for v in row)-{bg}:
        boxes=[]
        # Enumerate all boxes with height,width >=2; use prefix sums per color.
        ps=[[0]*(w+1) for _ in range(h+1)]
        for r in range(h):
            for c in range(w): ps[r+1][c+1]=ps[r][c+1]+ps[r+1][c]-ps[r][c]+(grid[r][c]==color)
        for r0 in range(h):
            for r1 in range(r0+1,h):
