                        n=ps[r1+1][c1+1]-ps[r0][c1+1]-ps[r1+1][c0]+ps[r0][c0]
                        if n/area>=0.75:
                            boxes.append((r0,c0,r1,c1,area,n))
        # keep inclusion-maximal qualifying boxes
        maximal=[]
        for b in boxes:
            a0,b0,a1,b1,area,n=b
            if not any(x[0]<=a0 and x[1]<=b0 and x[2]>=a1 and x[3]>=b1 and x[4]>area for x in boxes):
                maximal.append(b)
